#include "folder_collector.hpp"
#include <fstream>
#include <iostream>
#include <stdexcept>
int main(){try{namespace fs=std::filesystem;auto root=fs::temp_directory_path()/"kr_mycelia_collector";fs::remove_all(root);fs::create_directories(root/"KALYX");fs::create_directories(root/"MDraft");auto stale=root/"KALYX"/"README.md",current=root/"MDraft"/"README.md";{std::ofstream o(stale);o<<"# KALYX\nOld removed project.";}{std::ofstream o(current);o<<"# MDraft\nNative Markdown Workspace Editor.";}mycelia::DynamicAssociativeDatabase db;auto stale_record=krmemory::collect_changed_file(db,stale,{root});fs::remove_all(root/"KALYX");auto reconciled=krmemory::reconcile_collected_root(db,root,{root});if(db.get_sql_record(stale_record.signature))throw std::runtime_error("deleted source remained active");if(reconciled.removed!=1)throw std::runtime_error("stale source was not reconciled");mycelia::sql::Row filter;filter["source_key"]=krmemory::normalized_source_key(current);auto records=db.query_sql_like("imported_memory",filter);if(records.size()!=1||mycelia::sql::display(records.front().data.at("content")).find("Native Markdown") == std::string::npos)throw std::runtime_error("current source missing");if(mycelia::sql::display(records.front().data.at("project"))!="MDraft")throw std::runtime_error("project association missing");{std::ofstream o(current);o<<"# MDraft\nUpdated editor content.";}auto updated=krmemory::collect_changed_file(db,current,{root});if(updated.signature!=records.front().signature||db.query_sql_like("imported_memory",filter).size()!=1)throw std::runtime_error("changed source created duplicate");fs::remove_all(root);std::cout<<"PASS: approved root reconciliation removes stale sources, associates projects and upserts current files\n";return 0;}catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<'\n';return 1;}}
